import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.PriorityQueue;

public class Main {
    static class Edge {
        int to;
        int time;
        int cost;

        Edge(int to, int time, int cost) {
            this.to = to;
            this.time = time;
            this.cost = cost;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokenizer = null;

        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            tokenizer = new StringTokenizer(line);
            break;
        }

        if (tokenizer == null) return;

        int V = Integer.parseInt(tokenizer.nextToken());
        int N = Integer.parseInt(tokenizer.nextToken());
        int M = Integer.parseInt(tokenizer.nextToken());

        ArrayList<Edge>[] adj = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int i = 0; i < M; i++) {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            int u = Integer.parseInt(tokenizer.nextToken());
            int v = Integer.parseInt(tokenizer.nextToken());
            int t = Integer.parseInt(tokenizer.nextToken());
            int p = Integer.parseInt(tokenizer.nextToken());

            adj[u].add(new Edge(v, t, p));
            adj[v].add(new Edge(u, t, p));
        }

        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        int X = Integer.parseInt(tokenizer.nextToken());
        int Y = Integer.parseInt(tokenizer.nextToken());

        if (X == Y) {
            System.out.println(0);
            return;
        }

        int[][] dist = new int[N + 1][V + 1];
        int INF = 0x3f3f3f3f;
        for (int i = 1; i <= N; i++) {
            Arrays.fill(dist[i], INF);
        }

        // Fila de prioridade guardando estados compactados em um long:
        // bits 62..24: tempo (d)
        // bits 23..8: vértice (u)
        // bits 7..0: custo gasto (cost)
        PriorityQueue<Long> pq = new PriorityQueue<>();

        dist[X][0] = 0;
        pq.add(((long) 0 << 24) | ((long) X << 8) | 0);

        int ans = INF;

        while (!pq.isEmpty()) {
            long curr = pq.poll();
            int cost = (int) (curr & 0xFF);
            int u = (int) ((curr >> 8) & 0xFFFF);
            int d = (int) (curr >> 24);

            if (d > dist[u][cost]) continue;

            if (u == Y) {
                ans = d;
                break;
            }

            for (Edge edge : adj[u]) {
                int nextCost = cost + edge.cost;
                if (nextCost <= V) {
                    int nextDist = d + edge.time;
                    if (nextDist < dist[edge.to][nextCost]) {
                        dist[edge.to][nextCost] = nextDist;
                        long nextState = ((long) nextDist << 24) | ((long) edge.to << 8) | nextCost;
                        pq.add(nextState);
                    }
                }
            }
        }

        if (ans >= INF) {
            System.out.println(-1);
        } else {
            System.out.println(ans);
        }
    }
}
```

